#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("wartosci.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    int cel = 11;
    int cnt = 0;
    cout << "Pary o sumie " << cel << ":" << endl;
    for (int i = 0; i < (int)dane.size(); i++) {
        for (int j = i + 1; j < (int)dane.size(); j++) {
            if (dane[i] + dane[j] == cel) {
                cout << "   (" << dane[i] << ", " << dane[j] << ")" << endl;
                cnt++;
            }
        }
    }
    cout << "Liczba par: " << cnt << endl;
    return 0;
}
```

